int countVowels(const string& s) {
    int count = 0;
    for (char ch : s) {
        ch = tolower(ch);
        if (ch == 'a' || ch == 'e' || ch == 'i' || ch == 'o' || ch == 'u') count++;
    }
    return count;
}
